<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Maze Discovery — 24 Bots</title>
<style>
  :root { color-scheme: dark; }
  * { box-sizing: border-box; }
  body {
    margin: 0; padding: 18px;
    background: #14161c; color: #e7e9ee;
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    display: flex; flex-direction: column; align-items: center; gap: 14px;
  }
  h1 { font-size: 18px; font-weight: 600; margin: 0; letter-spacing: .3px; }
  #hud {
    display: flex; gap: 22px; align-items: center; flex-wrap: wrap;
    justify-content: center;
    background: #1c1f28; border: 1px solid #2a2e3a; border-radius: 10px;
    padding: 10px 18px;
  }
  .stat { display: flex; flex-direction: column; align-items: center; min-width: 74px; }
  .stat .label { font-size: 11px; text-transform: uppercase; letter-spacing: .6px; color: #8b90a0; }
  .stat .val { font-size: 22px; font-weight: 700; font-variant-numeric: tabular-nums; }
  #reset {
    cursor: pointer; border: 1px solid #3a4054; background: #262b38; color: #e7e9ee;
    font-size: 14px; font-weight: 600; padding: 8px 16px; border-radius: 8px;
  }
  #reset:hover { background: #313749; }
  #reset:active { transform: translateY(1px); }
  #maze {
    line-height: 0; border-radius: 10px; overflow: hidden;
    box-shadow: 0 8px 30px rgba(0,0,0,.45); border: 1px solid #2a2e3a;
  }
  canvas { display: block; background: #eef1f6; }
  .legend { font-size: 12px; color: #8b90a0; max-width: 520px; text-align: center; }
</style>
</head>
<body>
  <h1>Maze Discovery — 24 bots explore (DFS / Trémaux)</h1>
  <div id="hud">
    <div class="stat"><span class="label">Completed</span><span class="val"><span id="completed">0</span>/24</span></div>
    <div class="stat"><span class="label">Timer (ticks)</span><span class="val" id="timer">0</span></div>
    <button id="reset">Reset</button>
  </div>
  <div id="maze"><canvas id="cv"></canvas></div>
  <div class="legend">
    Bots start knowing only their own cell. They learn walls by moving, backtrack out of
    dead ends (marking them dead), and never fully re-explore a branch. Green = spawn, red = exit.
    Timer freezes when the last bot arrives.
  </div>

<script>
(() => {
  "use strict";

  // ---------- config ----------
  const N = 21;              // rows == cols (>= 15)
  const CELL = 24;           // px per cell -> canvas 504px (>= 400)
  const NBOTS = 24;
  const STEP_MS = 70;        // auto-play speed (visual only)

  const spawn = { r: 0, c: 0 };
  const exit  = { r: N - 1, c: N - 1 };

  const D   = { n: [-1, 0], s: [1, 0], e: [0, 1], w: [0, -1] };
  const OPP = { n: "s", s: "n", e: "w", w: "e" };

  // ---------- deterministic RNG ----------
  function mulberry32(a) {
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  // all 24 permutations of the four directions -> one per bot (max spread)
  function permute(arr) {
    if (arr.length <= 1) return [arr];
    const out = [];
    arr.forEach((v, i) => {
      const rest = arr.slice(0, i).concat(arr.slice(i + 1));
      permute(rest).forEach(p => out.push([v, ...p]));
    });
    return out;
  }
  const PERMS = permute(["n", "e", "s", "w"]); // exactly 24

  // ---------- state ----------
  let cells = [];      // cells[r][c].walls = {n,e,s,w}
  let bots = [];
  let elapsed = 0;
  let currentSeed = 1;
  let running = false;

  // ---------- maze generation (recursive backtracker) ----------
  function buildMaze(seed) {
    const rng = mulberry32(seed >>> 0);
    cells = [];
    for (let r = 0; r < N; r++) {
      const row = [];
      for (let c = 0; c < N; c++) row.push({ walls: { n: true, e: true, s: true, w: true } });
      cells.push(row);
    }
    const vis = Array.from({ length: N }, () => new Array(N).fill(false));
    const stack = [[0, 0]];
    vis[0][0] = true;
    while (stack.length) {
      const [r, c] = stack[stack.length - 1];
      const nb = [];
      for (const d of ["n", "e", "s", "w"]) {
        const nr = r + D[d][0], nc = c + D[d][1];
        if (nr >= 0 && nr < N && nc >= 0 && nc < N && !vis[nr][nc]) nb.push([d, nr, nc]);
      }
      if (nb.length) {
        const [d, nr, nc] = nb[Math.floor(rng() * nb.length)];
        cells[r][c].walls[d] = false;
        cells[nr][nc].walls[OPP[d]] = false;
        vis[nr][nc] = true;
        stack.push([nr, nc]);
      } else {
        stack.pop();
      }
    }
  }

  function isOpen(r, c, d) { return cells[r][c].walls[d] === false; }

  // ---------- bots ----------
  function buildBots() {
    bots = [];
    for (let i = 0; i < NBOTS; i++) {
      const key = spawn.r + "," + spawn.c;
      bots.push({
        r: spawn.r, c: spawn.c,     // current logical cell
        pr: spawn.r, pc: spawn.c,   // previous cell (for smooth interpolation)
        stack: [],                  // DFS backtrack stack (ancestor cells)
        visited: new Set([key]),
        path: [{ r: spawn.r, c: spawn.c }],
        deadEnds: [],
        finishTick: null,
        dirOrder: PERMS[i % PERMS.length],
        color: "hsl(" + Math.round((i * 360) / NBOTS) + ",72%,52%)",
      });
    }
  }

  // one logical move for a single bot (forward into a new cell, or backtrack one cell)
  function botStep(b) {
    if (b.finishTick !== null) return;
    const r = b.r, c = b.c;

    // look for an unvisited neighbor reachable through a passage, in this bot's preference order
    let moved = false;
    for (const d of b.dirOrder) {
      if (!isOpen(r, c, d)) continue;                 // wall -> can't go
      const nr = r + D[d][0], nc = c + D[d][1];
      const k = nr + "," + nc;
      if (b.visited.has(k)) continue;                 // already knows this cell -> don't re-explore
      // move forward
      b.stack.push({ r, c });
      b.pr = r; b.pc = c;
      b.r = nr; b.c = nc;
      b.visited.add(k);
      b.path.push({ r: nr, c: nc });
      moved = true;
      break;
    }

    if (!moved) {
      // dead end / fully explored branch -> record as dead and backtrack one cell
      b.deadEnds.push({ r, c });
      if (b.stack.length) {
        const back = b.stack.pop();
        b.pr = r; b.pc = c;
        b.r = back.r; b.c = back.c;
        b.path.push({ r: back.r, c: back.c });
      }
    }

    // arrival?
    if (b.r === exit.r && b.c === exit.c) b.finishTick = elapsed;
  }

  function allFinished() { return bots.every(b => b.finishTick !== null); }

  // advance the whole simulation exactly one tick (deterministic)
  function step() {
    if (allFinished()) return;   // timer frozen after last arrival
    elapsed++;
    for (const b of bots) botStep(b);
  }

  // ---------- rendering ----------
  const canvas = document.getElementById("cv");
  const ctx = canvas.getContext("2d");
  canvas.width = N * CELL;
  canvas.height = N * CELL;

  const completedEl = document.getElementById("completed");
  const timerEl = document.getElementById("timer");

  function drawMaze() {
    ctx.fillStyle = "#eef1f6";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // spawn & exit cells
    ctx.fillStyle = "rgba(46,180,90,.35)";
    ctx.fillRect(spawn.c * CELL, spawn.r * CELL, CELL, CELL);
    ctx.fillStyle = "rgba(220,60,60,.40)";
    ctx.fillRect(exit.c * CELL, exit.r * CELL, CELL, CELL);

    // walls
    ctx.strokeStyle = "#2b2f3a";
    ctx.lineWidth = 2;
    ctx.lineCap = "round";
    ctx.beginPath();
    for (let r = 0; r < N; r++) {
      for (let c = 0; c < N; c++) {
        const x = c * CELL, y = r * CELL, w = cells[r][c].walls;
        if (w.n) { ctx.moveTo(x, y); ctx.lineTo(x + CELL, y); }
        if (w.w) { ctx.moveTo(x, y); ctx.lineTo(x, y + CELL); }
        if (w.s) { ctx.moveTo(x, y + CELL); ctx.lineTo(x + CELL, y + CELL); }
        if (w.e) { ctx.moveTo(x + CELL, y); ctx.lineTo(x + CELL, y + CELL); }
      }
    }
    ctx.stroke();
  }

  function render(frac) {
    drawMaze();

    const rad = CELL * 0.28;
    for (const b of bots) {
      const f = b.finishTick !== null ? 1 : frac;
      const cx = (b.pc + 0.5 + (b.c - b.pc) * f) * CELL;
      const cy = (b.pr + 0.5 + (b.r - b.pr) * f) * CELL;
      ctx.beginPath();
      ctx.arc(cx, cy, rad, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.globalAlpha = 0.9;
      ctx.fill();
      ctx.globalAlpha = 1;
      ctx.lineWidth = 1.5;
      ctx.strokeStyle = "rgba(0,0,0,.35)";
      ctx.stroke();
    }

    completedEl.textContent = bots.filter(b => b.finishTick !== null).length;
    timerEl.textContent = elapsed;
  }

  // ---------- animation loop (visual only; never affects logic under scripting) ----------
  let lastStep = 0;
  function frame(now) {
    if (running && !allFinished()) {
      if (now - lastStep >= STEP_MS) { step(); lastStep = now; }
    }
    const frac = running && !allFinished()
      ? Math.min(1, (now - lastStep) / STEP_MS)
      : 1;
    render(frac);
    requestAnimationFrame(frame);
  }

  // ---------- lifecycle ----------
  function init(seed) {
    currentSeed = seed >>> 0;
    buildMaze(currentSeed);
    buildBots();
    elapsed = 0;
  }

  // ---------- scripting API ----------
  const game = {
    tick(n) {
      running = false;              // scripted control -> auto-play yields fully
      n = Math.max(0, n | 0);
      for (let i = 0; i < n; i++) step();
      render(1);
    },
    reset(seed) {
      const s = (seed === undefined || seed === null) ? ((Math.random() * 2147483647) >>> 0) : (seed >>> 0);
      init(s);
      running = false;             // deterministic until driven by tick() (or the Reset button)
      render(1);
    },
    walls(r, c) {
      const w = cells[r][c].walls;
      return { n: w.n, e: w.e, s: w.s, w: w.w };
    },
    get elapsed() { return elapsed; },
    get size() { return { rows: N, cols: N }; },
    get spawn() { return { r: spawn.r, c: spawn.c }; },
    get exit() { return { r: exit.r, c: exit.c }; },
    get bots() { return bots; },
    get seed() { return currentSeed; },
  };
  window.game = game;

  // Reset button: fresh random maze AND resume live auto-play.
  document.getElementById("reset").addEventListener("click", () => {
    init((Math.random() * 2147483647) >>> 0);
    running = true;
    lastStep = performance.now();
  });

  // boot: start a live demo run
  init(20260730);
  running = true;
  requestAnimationFrame((t) => { lastStep = t; frame(t); });
})();
</script>
</body>
</html>
